import{_ as t,o,c as s,a5 as a}from"./chunks/framework.BkFmai_x.js";const h=JSON.parse('{"title":"Windows Desktop (WPF)","description":"","frontmatter":{},"headers":[],"relativePath":"platforms/windows.md","filePath":"platforms/windows.md","lastUpdated":1784290844000}'),n={name:"platforms/windows.md"};function r(i,e,d,c,p,l){return o(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="windows-desktop-wpf" tabindex="-1">Windows Desktop (WPF) <a class="header-anchor" href="#windows-desktop-wpf" aria-label="Permalink to &quot;Windows Desktop (WPF)&quot;">​</a></h1><p><code>VaultGuard.WPF</code> is a standalone Windows desktop app - no separate server required. It runs the shared core in-process against a local SQLite vault (or a remote database provider, configured from Settings), protected by the exact same key derivation, AES-256-GCM encryption and constant-time verification as the server-backed builds - see <a href="/PasswordManagerApp/guide/security">Security Model</a>.</p><p>Distributed as an <code>.exe</code> (Inno Setup) or <code>.msi</code> (WiX) installer, both bundling the .NET runtime.</p><div class="warning custom-block"><p class="custom-block-title">Screenshots not yet available</p><p>This build environment doesn&#39;t run a Windows desktop session, so there&#39;s no way to capture real screenshots here. Once someone takes them on Windows, drop them into <code>screenshots/wpf/{dark,light}/</code> in the repository and they&#39;ll show up here automatically.</p></div>',4)])])}const m=t(n,[["render",r]]);export{h as __pageData,m as default};
